    $("result-state").textContent = !d ? "方案产物" : view.expired ? "运行服务已到期 · 源码与证据保留" : `自动检查 ${d.tests.passedCount}/${d.tests.total} 通过 · 等待人工体验`;
    const url = d && !view.expired ? previewURL(d.demoUrl, document.baseURI) : null;
