        .join("\n");
      for (const id of ["delivery-demo", "computer-demo"]) {
        if (expired) $(id).removeAttribute("href");
        else $(id).href = new URL(delivery.demoUrl, document.baseURI).href;
        $(id).textContent = expired ? "运行地址已到期，请重新执行目标" : "打开 Demo ↗";
