    this.renderMission();
    const delivery = missionView(this.store.selected).delivery;
    if (delivery?.kind === "upstream") {
      try {
        const response = await fetch(new URL(delivery.manifestUrl, document.baseURI));
        if (!response.ok) throw new Error();
