.team-panel textarea {
  background: #0c141c80;
  color: #dde4d9;
  border: 1px solid #ffffff13;
  border-radius: 8px;
  resize: none;
  min-height: 62px;
  padding: 10px;
  font-size: 10px;
  line-height: 1.7;
  width: 100%;
}
.team-panel select {
  margin-top: 10px;
  background: #29343d;
  color: #c5d2c4;
  border: 1px solid #ffffff15;
  padding: 8px;
  border-radius: 6px;
  font-size: 10px;
}
.mode-description {
  font-size: 9px;
  line-height: 1.6;
  color: #8e9ba4;
  margin: 7px 0;
}
.voice-options {
  display: flex;
  gap: 16px;
  font-size: 9px;
  color: #b4c1bb;
  align-items: center;
}
.voice-options label {
  display: flex;
  align-items: center;
  gap: 4px;
}
.voice-options input {
  accent-color: #b5c79f;
  margin: 0;
}
.voice-connection {
  font-size: 8px;
  color: #99b18e;
  margin: 7px 0 10px;
}
.team-buttons {
  display: flex;
  align-items: center;
  gap: 5px;
}
.team-buttons .primary-button {
  width: auto;
  flex: 1;
  gap: 8px;
  padding: 9px 10px;
  font-size: 10px;
}
.team-buttons > button:not(.primary-button) {
  font-size: 9px;
  white-space: nowrap;
  border: 1px solid #ffffff16;
  border-radius: 6px;
  padding: 9px 6px;
}
.team-progress {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 13px 0 8px;
  border-bottom: 1px solid #ffffff0d;
}
.team-progress i {
  width: 5px;
  height: 5px;
  background: #b4cc94;
  border-radius: 50%;
}
.team-progress strong {
  font-size: 9px;
  font-weight: 400;
  color: #c6d2c0;
  flex: 1;
}
.team-progress button {
  font-size: 8px;
  color: #91a19e;
  padding: 3px 5px;
}
.team-notice {
  font-size: 9px;
  line-height: 1.6;
  color: #e6ba8f;
  margin: 5px 0;
}
.team-notice:empty {
  display: none;
}
.workspace-tabs {
  display: flex;
  justify-content: space-between;
  color: #85949e;
  font-size: 8px;
  padding: 9px 0 6px;
}
.workspace-tabs b {
  font-weight: 400;
  color: #bacbad;
}
.artifact-list {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  max-height: 62px;
  overflow: auto;
  flex-shrink: 0;
  padding-bottom: 6px;
}
.artifact-item {
  font-size: 8px;
  background: #afc49a10;
  border: 1px solid #afc49a22;
  border-radius: 4px;
  padding: 5px 6px;
  color: #b4c5a6;
}
.event-log {
  overflow: auto;
  flex: 1;
  min-height: 45px;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: #5a6c6533 transparent;
}
.event-item {
  border-left: 1px solid #a6ba9433;
  margin: 7px 0;
  padding: 1px 0 1px 9px;
}
.event-item strong {
  font-size: 9px;
  color: #c3d0bd;
  font-weight: 400;
}
.event-item p {
  font-size: 8px;
  line-height: 1.7;
  color: #899ba1;
  margin: 4px 0;
}
.event-empty {
  font-size: 9px;
  line-height: 1.8;
  color: #74858c;
}
.resident-card {
  right: 24px;
  top: 155px;
  width: 246px;
  padding: 17px;
}
.agent-badges {
  display: flex;
  gap: 6px;
  margin: 12px 0 5px;
}
.agent-badges span {
  font-size: 9px;
  padding: 4px 8px;
  border: 1px solid #ffffff13;
  border-radius: 5px;
  color: #bfceaf;
  background: #afc49a10;
}
.agent-badges #agent-state {
  color: #8f9da7;
  background: #0c141c55;
}
.agent-badges #agent-state[data-status="working"],
.agent-badges #agent-state[data-status="reviewing"],
.agent-badges #agent-state[data-status="testing"] {
  color: #e3d0a8;
  border-color: #cfb48655;
}
.agent-badges #agent-state[data-status="blocked"],
.agent-badges #agent-state[data-status="error"] {
  color: #e5ad99;
  border-color: #b7876e55;
}
.agent-badges #agent-state[data-status="done"] {
  color: #b4d3a5;
}
.agent-instance {
  font: 8px monospace;
  color: #697d89;
  margin: 6px 0;
}
.resident-description {
  min-height: 0;
  margin: 10px 0 15px;
}
.resident-info {
  margin: 16px 0 8px;
}
.resident-info p {
  font-size: 9px;
  max-width: 130px;
  line-height: 1.7;
}
.agent-actions {
  display: flex;
  gap: 8px;
  margin: 0 0 12px;
}
.agent-actions button {
  font-size: 9px;
  padding: 7px;
  border: 1px solid #ffffff15;
  border-radius: 5px;
  color: #b1c0b3;
  flex: 1;
  white-space: nowrap;
}
.resident-label[data-status="working"],
.resident-label[data-status="reviewing"],
.resident-label[data-status="testing"] {
  border-color: #ddc58f99;
  color: #efd9a8;
}
.resident-label[data-status="blocked"] {
  border-color: #df9c8377;
  color: #e4ac98;
}
.resident-label.speaking {
  box-shadow: 0 0 14px #d6e3bb33;
  border-color: #d6e3bb;
  background: #384d3df2;
}
.speech-bar {
  position: fixed;
  bottom: 150px;
  left: 50%;
  transform: translateX(-50%);
  width: min(480px, calc(100vw - 40px));
  border-radius: 12px;
  padding: 14px 18px;
}
.speech-top {
  display: flex;
  gap: 8px;
  align-items: center;
}
.speech-top strong {
  font-size: 11px;
  font-weight: 400;
  color: #d9e5c5;
}
.speech-top > span:last-of-type {
  font-size: 8px;
  color: #95a4a6;
  margin-left: auto;
}
.speech-top button {
  font-size: 8px;
  color: #93a095;
  padding: 3px;
  border-radius: 3px;
}
.speech-bar p {
  font-size: 12px;
  line-height: 1.8;
  color: #d2d7ca;
  margin: 9px 0 1px;
}
.speech-pulse {
  display: flex;
  gap: 2px;
  align-items: center;
  height: 15px;
}
.speech-pulse i {
  background: #c3d7a6;
  width: 2px;
  height: 4px;
  animation: voice-pulse 0.65s alternate infinite;
}
.speech-pulse i:nth-child(2) {
  animation-delay: -0.4s;
}
.speech-pulse i:nth-child(3) {
  animation-delay: -0.2s;
}
.artifact-dialog {
  width: min(90vw, 700px);
  max-height: 80vh;
  overflow: auto;
}
.artifact-dialog pre {
  font-family: inherit;
  white-space: pre-wrap;
  font-size: 12px;
  line-height: 1.9;
  color: #c0ccc6;
  overflow-wrap: anywhere;
}
.artifact-dialog h2 {
  font-size: 22px;
}
.mobile-action {
  display: none;
}
.walking .team-panel {
  display: none;
}
@keyframes voice-pulse {
  to {
    height: 14px;
  }
}
@media (min-width: 1500px) {
  .team-panel {
    left: 40px;
    width: 296px;
    top: 170px;
    bottom: 175px;
  }
  .resident-card {
    right: 40px;
    top: 170px;
    width: 265px;
  }
  .speech-bar {
    bottom: 170px;
  }
}
@media (max-width: 1100px) and (min-width: 761px) {
  .team-panel {
    width: 230px;
    left: 18px;
    padding: 13px;
  }
  .resident-card {
    right: 18px;
    width: 210px;
    padding: 13px;
  }
  .team-panel-top > span:last-child {
    display: none;
  }
  .team-buttons > button:not(.primary-button) {
    padding: 9px 4px;
    font-size: 8px;
  }
  .voice-options {
    gap: 10px;
    font-size: 8px;
  }
  .agent-actions {
    gap: 3px;
  }
  .agent-actions button {
    font-size: 8px;
    padding: 6px;
  }
}
@media (max-width: 760px), (max-height: 560px) {
  .mobile-action {
    display: block;
    position: fixed;
    top: 120px;
    z-index: 3;
    font-size: 10px;
    border-radius: 7px;
    width: auto;
    padding: 8px 12px;
  }
  .mobile-action#mobile-start {
    left: 20px;
  }
  .mobile-action#toggle-workspace {
    right: 20px;
    background: #1b2933dd;
    border: 1px solid #ffffff21;
  }
  .team-panel {
    display: none;
    top: 158px;
    left: 16px;
    bottom: 153px;
    width: calc(100vw - 32px);
    max-height: 510px;
    z-index: 4;
    background: #15222bf5;
  }
  .workspace-open .team-panel {
    display: flex;
  }
  .team-panel textarea {
    min-height: 57px;
  }
  .team-panel-top > span:last-child {
    display: block;
  }
  .resident-card {
    bottom: 156px;
    top: auto;
    right: 16px;
    width: 184px;
    padding: 12px;
  }
  .agent-instance,
  .resident-description {
    display: none;
  }
  .agent-badges {
    margin: 7px 0 9px;
  }
  .agent-badges span {
    font-size: 8px;
    padding: 3px 6px;
  }
  .resident-info {
    margin: 0 0 7px;
  }
  .resident-info p {
    max-width: 117px;
    font-size: 8px;
  }
  .resident-picker {
    margin: 0 0 9px;
  }
  .agent-actions {
    margin-bottom: 8px;
    gap: 4px;
  }
  .agent-actions button {
    font-size: 8px;
    padding: 6px 4px;
  }
  .resident-card #enter-resident {
    display: none;
  }
  .speaking .resident-card {
    display: none;
  }
  .speech-bar {
    bottom: 155px;
    padding: 12px 14px;
    z-index: 3;
  }
  .speech-bar p {
    font-size: 11px;
  }
  .speech-top strong {
    font-size: 10px;
  }
  .speech-top > span:last-of-type {
    font-size: 7px;
  }
  .speech-top button {
    font-size: 7px;
  }
  .workspace-open .speech-bar {
    display: none;
  }
}
@media (max-height: 560px) and (min-width: 761px) {
  .mobile-action {
    top: 90px;
  }
  .team-panel {
    top: 123px;
    bottom: 35px;
    left: 20px;
    width: 360px;
    max-height: calc(100vh - 150px);
    overflow-y: auto;
    scrollbar-width: thin;
  }
  .team-panel textarea,
  .team-panel select {
    display: block;
    width: 100%;
  }
  .event-log {
    max-height: 140px;
    min-height: 80px;
  }
  .resident-card {
    top: 100px;
    bottom: auto;
    right: 22px;
    width: 200px;
  }
  .agent-badges {
    margin: 5px 0;
  }
  .resident-info {
    gap: 10px;
  }
  .resident-info canvas {
    width: 32px;
    height: 32px;
  }
  .agent-actions {
    margin: 0;
  }
  .resident-picker {
    margin-bottom: 6px;
  }
  .speech-bar {
    bottom: 108px;
    width: 400px;
  }
  .voice-connection,
  .mode-description {
    display: none;
  }
  .team-panel textarea {
    min-height: 40px;
    max-height: 40px;
  }
  .goal-label {
    margin-top: 8px;
  }
  .team-progress {
    padding: 8px 0 5px;
  }
}
@media (max-height: 560px) {
  .workspace-open .team-panel {
    display: block;
    overflow-y: auto;
  }
}

