      let status = c.controller?.signal.aborted
        ? "stopped"
        : c.paused
          ? "paused"
          : c.running
            ? "running"
            : "stopped";
      if (last?.type === "run.complete") status = "done";
      if (last?.type === "run.error") status = "error";
      this.store.updateRun(this.goalId, this.runId, {
