    $("board-title").textContent = `共享白板 · ${goal.title}`;
    $("board-brief").textContent = goal.brief;
    $("board-criteria").replaceChildren();
    goal.criteria.forEach((criterion, index) => {
      const label = el("label", undefined, "criterion");
